<script setup lang="ts">
const api=useApi(),cart=useCartStore(),resetConfirm=ref(false),busy=ref(false),message=ref(''),actionError=ref('')
const {data:products,pending,error,refresh}=await useAsyncData('admin-overview-products',()=>api.adminProducts({pageSize:50}))
const {data:orders,refresh:refreshOrders}=await useAsyncData('admin-overview-orders',()=>api.orders())
async function reset(){resetConfirm.value=false;busy.value=true;actionError.value='';try{await api.reset();cart.clear();await clearNuxtData();await Promise.all([refresh(),refreshOrders()]);message.value='Архив восстановлен. Каталог и коллекции сброшены, тестовые заказы и корзина очищены.'}catch(e){actionError.value=errorMessage(e)}finally{busy.value=false}}
useSeoMeta({title:'Обзор демо-панели — Deadlock Family'})
</script>
<template><AdminShell title="Демонстрационная панель"><ApiState :pending="pending" :error="error" @retry="refresh()"/><div class="admin-stats"><div class="stat-card"><span>{{products?.total||0}}</span><p>Товаров в архиве</p></div><div class="stat-card"><span>{{products?.items.filter(p=>p.status==='published').length||0}}</span><p>Опубликовано</p></div><div class="stat-card"><span>{{orders?.length||0}}</span><p>Тестовых заказов</p></div></div><div class="form-panel"><h2>Архив в ваших руках</h2><p style="color:var(--muted);max-width:700px">Создайте товар, сохраните черновик и опубликуйте его. Откройте магазин и проверьте результат. Затем пройдите оформление тестового заказа — он появится во вкладке «Тестовые заказы».</p><div class="admin-actions"><NuxtLink to="/admin/products/new" class="btn btn-primary"><AppIcon name="plus" :size="17"/>Новый товар</NuxtLink><NuxtLink to="/admin/collections" class="btn">Управлять коллекциями</NuxtLink><NuxtLink to="/admin/orders" class="btn">Посмотреть заказы</NuxtLink></div></div><div class="api-scenarios"><span>Проверить состояния каталога:</span><NuxtLink to="/shop?scenario=empty" class="btn btn-small">Пустая выдача</NuxtLink><NuxtLink to="/shop?scenario=400" class="btn btn-small">Ошибка 400</NuxtLink><NuxtLink to="/shop?scenario=404" class="btn btn-small">Ошибка 404</NuxtLink><NuxtLink to="/shop?scenario=500" class="btn btn-small">Ошибка 500</NuxtLink></div><div class="form-actions"><button class="btn btn-danger" :disabled="busy" @click="resetConfirm=true"><AppIcon name="refresh" :size="16"/>{{busy?'Восстанавливаем…':'Сбросить демо-данные'}}</button><p v-if="message" class="notice success" role="status">{{message}}</p><p v-if="actionError" class="notice error" role="alert">{{actionError}}</p></div><ConfirmDialog v-if="resetConfirm" title="Начать новую историю?" message="Все изменения товаров, коллекций, корзины и тестовые заказы этой сессии будут удалены. Исходный каталог восстановится." confirm-label="Сбросить данные" @cancel="resetConfirm=false" @confirm="reset"/></AdminShell></template>
